{
  "aktywnosci": [
    {
      "tytul": "Wędrówka bucików do progu sali",
      "opis": "Dzieci zdejmują po jednym buciku i pod kierunkiem nauczyciela ustawiają je w rzędzie, jeden za drugim, od najdalszego kąta sali w stronę drzwi. Każdy przedszkolak po kolei przekłada swój bucik z końca na początek kolejki, aż pierwszy but dotknie progu. Zabawa uczy cierpliwości, współdziałania w grupie oraz bezpiecznie nawiązuje do tradycyjnych andrzejkowych zwyczajów."
    },
    {
      "tytul": "Tajemnicze kubeczki z symbolami",
      "opis": "Nauczyciel układa na dywanie nieprzezroczyste kubeczki, pod którymi ukryte są proste obrazki przedstawiające różne symbole (np. nutka – miłośnik muzyki, pędzel – mały artysta, serduszko – dobry przyjaciel, piłka – sportowiec). Chętne dzieci po kolei podnoszą wybrany kubeczek i wspólnie z grupą odgadują znaczenie wylosowanego symbolu. Aktywność rozwija mowę, logiczne myślenie oraz buduje radosną atmosferę wspólnej zabawy."
    },
    {
      "tytul": "Zaczarowane klucze do krainy wyobraźni",
      "opis": "Dzieci otrzymują duże szablony kluczy wycięte z grubego brystolu. Zadaniem przedszkolaków jest ozdobienie swoich kluczy za pomocą kredek, kolorowych ścinków papieru i miękkich kulek z bibuły przyklejanych klejem w sztyfcie. Gotowe prace posłużą do symbolicznego „otwarcia drzwi” do krainy andrzejkowych tańców i zabaw muzycznych."
    }
  ]
}
